const query = new URLSearchParams(location.search);
const asset = query.get("asset") || "";
const symbol = query.get("symbol") || asset;
const status = document.getElementById("status");
const canvas = document.getElementById("canvas");
let stage;

async function start() {
  if (!/^js\d{4}\p{Script=Han}$/u.test(asset) || !window.createjs) throw new Error("Invalid animation");
  if (symbol !== asset && symbol !== asset.slice(0,6)) throw new Error("Invalid symbol");
  const base = encodeURIComponent(asset) + "/";
  const assetUrl = file => (overrides.has(asset + "/" + file) ? "" : "../../movie/") + base + file;
  await new Promise((resolve,reject)=>{
    const script = document.createElement("script");
    script.src = assetUrl(asset + ".js");
    script.onload = resolve;
    script.onerror = reject;
    document.head.append(script);
  });
  const composition = Object.values(window.AdobeAn?.compositions || {})[0];
  if (!composition) throw new Error("Composition unavailable");
  const library = composition.getLibrary();
  const images = composition.getImages();
  const sheets = composition.getSpriteSheet();
  const assets = library.properties.manifest;
  await Promise.all(assets.map(({id,src})=>new Promise((resolve,reject)=>{
    const image = new Image();
    image.onload = () => { images[id] = image; resolve(); };
    image.onerror = reject;
    image.src = assetUrl(src);
  })));
  for (const entry of library.ssMetadata) {
    sheets[entry.name] = new createjs.SpriteSheet({images:[images[entry.name]],frames:entry.frames});
  }
  canvas.width = library.properties.width;
  canvas.height = library.properties.height;
  stage = new library.Stage(canvas);
  const Timeline = library[symbol];
  if (typeof Timeline !== "function") throw new Error("Timeline unavailable");
  const timeline = stage.addChild(new Timeline());
  timeline.gotoAndStop("pauseAndBtnSet");
  timeline.play();
  timeline.playBtn.visible = false;
  stage.enableMouseOver();
  stage.update();
  createjs.Ticker.framerate = library.properties.fps;
  createjs.Ticker.addEventListener("tick",stage);
  status.hidden = true;
  canvas.hidden = false;
}

window.addEventListener("pagehide",()=>{
  if (!stage) return;
  createjs.Ticker.removeEventListener("tick",stage);
  stage.enableMouseOver(0);
  stage.enableDOMEvents(false);
  stage.removeAllChildren();
},{once:true});

start().catch(()=>{
  status.textContent = "書き順を再生できませんでした。";
});
